// Block (composition) — an image gallery with two layouts: "showcase" (a large main
// image + a selectable thumbnail strip, for product/detail views) and "grid" (uniform
// tiles that open a lightbox). Contract: docs/rules/block-contract.md. Button/Stack/
// Grid/Dialog own their look + behavior; this Block only arranges the media slots and
// tracks the showcase selection. Mints no tokens. Replaces the former ProductGallery
// (= layout "showcase") and MediaGallery (= layout "grid").
import { useState } from "react";
import type { ReactNode, Ref } from "react";
import { Expand } from "../components/icons";
import { Button } from "../components/Button";
import { DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "../components/Dialog";
import { Media } from "../components/Media";
import { AspectRatio } from "../layouts/AspectRatio";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import "./Gallery.css";

export interface GalleryImage {
  /** Stable key. */
  id: string;
  /** The media element (usually an <img>). */
  node: ReactNode;
  /** Accessible description used for thumbnail / lightbox labels. */
  alt?: string;
}

export interface GalleryProps {
  /** Images to display. */
  images: GalleryImage[];
  /** "showcase" = main image + thumbnail strip; "grid" = tiles + lightbox. */
  layout?: "showcase" | "grid";
  /** Thumbnail columns in grid layout (responsive value supported). */
  columns?: number | { small: number; medium: number };
  /** Initially selected image (showcase layout). */
  defaultIndex?: number;
  /** Called when the showcase selection changes. */
  onIndexChange?: (index: number) => void;
  /** Accessible name for the gallery region. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

function clampIndex(index: number, count: number) {
  if (count === 0) return 0;
  return Math.min(Math.max(index, 0), count - 1);
}

export function Gallery({
  images,
  layout = "showcase",
  columns = { small: 2, medium: 3 },
  defaultIndex = 0,
  onIndexChange,
  "aria-label": ariaLabel = "Gallery",
  className,
  ref,
}: GalleryProps) {
  const [selectedIndex, setSelectedIndex] = useState(() => clampIndex(defaultIndex, images.length));

  const cls = className ? `sd-gallery ${className}` : "sd-gallery";

  if (layout === "grid") {
    return (
      <section ref={ref} aria-label={ariaLabel} className={cls}>
        <Grid columns={columns} gap="small" className="sd-gallery__grid">
          {images.map((image) => (
            <div key={image.id} className="sd-gallery__tile">
              {/* The lightbox button stays outside the Media clip, so its focus ring is not cut. */}
              <Media aria-hidden="true">
                <AspectRatio ratio={1} className="sd-gallery__tile-media">
                  {image.node}
                </AspectRatio>
              </Media>
              <DialogTrigger>
                <Button
                  variant="outline"
                  size="small"
                  isIconOnly
                  className="sd-gallery__view"
                  aria-label={`View ${image.alt ?? "image"}`}
                >
                  <Expand aria-hidden size="1em" />
                </Button>
                <DialogContent
                  className="sd-gallery__lightbox"
                  // Explicit: an image without alt text has no header, and a lightbox keeps its
                  // close floating over the media either way.
                  showCloseButton
                  header={
                    image.alt ? (
                      <DialogHeader>
                        <DialogTitle>{image.alt}</DialogTitle>
                      </DialogHeader>
                    ) : undefined
                  }
                >
                  <Media className="sd-gallery__lightbox-media">{image.node}</Media>
                </DialogContent>
              </DialogTrigger>
            </div>
          ))}
        </Grid>
      </section>
    );
  }

  const activeIndex = clampIndex(selectedIndex, images.length);
  const selectImage = (index: number) => {
    setSelectedIndex(index);
    onIndexChange?.(index);
  };

  return (
    <Stack ref={ref} gap="small" aria-label={ariaLabel} className={cls}>
      <Media>
        <AspectRatio ratio={1} className="sd-gallery__main">
          {images[activeIndex]?.node}
        </AspectRatio>
      </Media>
      {images.length > 0 && (
        <Stack direction="row" gap="x-small" wrap className="sd-gallery__thumbnails">
          {images.map((image, index) => (
            <Button
              key={image.id}
              variant="outline"
              size="large"
              isMediaOnly
              aria-current={index === activeIndex ? "true" : undefined}
              aria-label={`View ${image.alt ?? `image ${index + 1}`}`}
              onPress={() => selectImage(index)}
            >
              <span aria-hidden="true" className="sd-gallery__thumbnail-media">
                {image.node}
              </span>
            </Button>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

/* Gallery.css — .sd-gallery (Block)
   Arrangement only: two layouts. "showcase" shows a square main picture + a thumbnail row; "grid"
   lays out square tiles each with an overlaid lightbox trigger. Media owns each picture's corner and
   clip and AspectRatio its square, so nothing here clips: a tile that clipped itself cut the lightbox
   button's focus ring. Dialog owns the lightbox; Button/Grid/Stack own their look. No tokens. */
.sd-gallery {
  width: 100%;
  min-width: 0;
}

/* showcase layout */
.sd-gallery__main {
  place-items: center;
}

.sd-gallery__thumbnails {
  width: 100%;
}

.sd-gallery__thumbnail-media {
  display: grid;
  width: 100%;
  height: 100%;
  overflow: hidden;
  place-items: center;
}

/* grid layout */
.sd-gallery__tile {
  position: relative;
}

.sd-gallery__tile-media {
  place-items: center;
}

.sd-gallery__view {
  position: absolute;
  inset-block-start: var(--sd-space-2x-small);
  inset-inline-end: var(--sd-space-2x-small);
}

.sd-gallery__lightbox-media {
  display: grid;
  place-items: center;
  max-height: 80vh;
  overflow: hidden;
}
